import{az as a,P as t,Q as l,aQ as s}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const F=JSON.parse('{"title":"渲染优化（对比 Fiber）","description":"","frontmatter":{},"headers":[],"relativePath":"框架/vue/vue/源码解析/渲染优化.md","filePath":"框架/vue/vue/源码解析/渲染优化.md","lastUpdated":1785246304000}'),o={name:"框架/vue/vue/源码解析/渲染优化.md"};function r(n,e,c,p,d,i){return t(),l("div",null,[...e[0]||(e[0]=[s(`<h1 id="渲染优化-对比-fiber" tabindex="-1">渲染优化（对比 Fiber） <a class="header-anchor" href="#渲染优化-对比-fiber" aria-label="Permalink to “渲染优化（对比 Fiber）”">​</a></h1><p>Vue <strong>没有</strong>对等的 Fiber：不做「把一次更新拆成可中断工作单元、按优先级调度」这套架构。</p><p>它走的是另一条路——<strong>少做无效工作</strong>：细粒度响应式缩小更新范围，编译期给运行时留下快捷路径。</p><table tabindex="0"><thead><tr><th></th><th>React Fiber / 并发渲染</th><th>Vue 3</th></tr></thead><tbody><tr><td>核心问题</td><td>一次更新太重 → 可中断、按优先级调度</td><td>更新范围太大 → 从源头缩小 Diff</td></tr><tr><td>手段</td><td>工作单元 + Scheduler + <code>startTransition</code> 等</td><td>响应式依赖 + 编译期提示</td></tr><tr><td>结果</td><td>Render 可暂停 / 恢复</td><td>运行时尽量只碰会变的节点</td></tr></tbody></table><p>可对照 React 侧：<a href="/page__blog-doc/框架/react/react/fiber">Fiber</a>、<a href="/page__blog-doc/框架/react/react/并发渲染">并发渲染</a>。</p><h2 id="_1-细粒度响应式" tabindex="-1">1. 细粒度响应式 <a class="header-anchor" href="#_1-细粒度响应式" aria-label="Permalink to “1. 细粒度响应式”">​</a></h2><p>Vue 用 <code>Proxy</code> 在读取时收集依赖、写入时精确通知。</p><ul><li>改哪个数据，通常只触发订阅了它的 effect / 组件</li><li>组件更新边界往往比 React「状态变了整棵子树默认重渲染」更小</li><li><code>computed</code> 自带缓存，依赖不变不重算</li></ul><p>这是运行时的「少更新谁」；下面几项是编译期的「少 Diff 什么」。</p><h2 id="_2-静态提升-hoiststatic" tabindex="-1">2. 静态提升（hoistStatic） <a class="header-anchor" href="#_2-静态提升-hoiststatic" aria-label="Permalink to “2. 静态提升（hoistStatic）”">​</a></h2><p>模板里不参与更新的节点，编译后提到 <code>render</code> 外，只创建一次，之后复用。</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">template</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">    &lt;</span><span style="color:#F07178;">p</span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;">永远不变</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">p</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">    &lt;</span><span style="color:#F07178;">p</span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;">{{ msg }}</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">p</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;/</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">template</span><span style="color:#89DDFF;">&gt;</span></span></code></pre></div><p>直觉上：静态 <code>&lt;p&gt;</code> 不会在每次渲染里重新 <code>createVNode</code>；动态部分才进更新路径。</p><blockquote><p>Vue2：不论静动态，每次更新常会重新创建相关 VNode。<br> Vue3：静态部分提升后可直接复用。</p></blockquote><h2 id="_3-patchflag-静态标记" tabindex="-1">3. PatchFlag（静态标记） <a class="header-anchor" href="#_3-patchflag-静态标记" aria-label="Permalink to “3. PatchFlag（静态标记）”">​</a></h2><p>编译器分析节点「哪部分是动态的」，把结果编码成整数 flag，挂到 VNode 上。</p><p>运行时 Diff 时：</p><ul><li>有 flag → 按位判断，只比 text / class / props 等必要项</li><li>静态节点可直接跳过</li></ul><p>例如动态文本大致会带上「TEXT」类标记，更新时走快速路径，而不是全量比 props。</p><p>你笔记里「vue3 如何变快」提到的静态标记，指的就是这个。</p><h2 id="_4-block-tree-树扁平化" tabindex="-1">4. Block Tree（树扁平化） <a class="header-anchor" href="#_4-block-tree-树扁平化" aria-label="Permalink to “4. Block Tree（树扁平化）”">​</a></h2><p>稳定结构的模板会收成一个 <strong>Block</strong>：内部动态节点被收集到扁平的 <code>dynamicChildren</code> 列表。</p><p>更新时：</p><ul><li>不必整棵 VDOM 树一层层遍历</li><li>直接遍历动态节点列表做 patch</li><li>Diff 成本更接近「动态节点数」，而不是「模板总节点数」</li></ul><p><code>v-if</code> / <code>v-for</code> 会引入结构变化，可能新建 Block 或在部分场景回退到更完整的 Diff；列表仍要稳定 <code>key</code>，见 <a href="./虚拟节点和diff算法">虚拟节点和 diff</a>。</p><h2 id="_5-其它相关优化" tabindex="-1">5. 其它相关优化 <a class="header-anchor" href="#_5-其它相关优化" aria-label="Permalink to “5. 其它相关优化”">​</a></h2><table tabindex="0"><thead><tr><th>手段</th><th>作用</th></tr></thead><tbody><tr><td>事件侦听器缓存（cacheHandlers）</td><td>内联事件在合理时可缓存，减少无意义的更新追踪</td></tr><tr><td><code>v-once</code> / <code>v-memo</code></td><td>手动跳过整段或按条件跳过更新</td></tr><tr><td>异步组件 / <code>Suspense</code></td><td>推迟加载，降低首屏与重块同步压力</td></tr><tr><td>SSR 静态内容</td><td>大量静态可走字符串 / static vnode，减少客户端创建成本</td></tr></tbody></table><h2 id="和-fiber-怎么记" tabindex="-1">和 Fiber 怎么记 <a class="header-anchor" href="#和-fiber-怎么记" aria-label="Permalink to “和 Fiber 怎么记”">​</a></h2><ul><li><strong>Fiber</strong>：工程太大 → 拆成小任务，边做边让路给用户输入（<strong>怎么调度</strong>）</li><li><strong>Vue 编译优化 + 响应式</strong>：工程里很多活根本不用做 → 编译期标好、运行时跳过（<strong>怎么少算</strong>）</li></ul><p>Vue 目前没有官方、生产级的「可中断并发渲染」；卡顿场景更常见的做法是：理清响应式边界、拆组件、<code>v-memo</code>、异步拆分，而不是 React 那套 Transition API。</p><h2 id="简单理解" tabindex="-1">简单理解 <a class="header-anchor" href="#简单理解" aria-label="Permalink to “简单理解”">​</a></h2><p>React 用 Fiber 把重渲染变得「可打断」；Vue 用编译器 + 响应式把重渲染变得「更轻」。目标相近，手段不同。</p>`,32)])])}const f=a(o,[["render",r]]);export{F as __pageData,f as default};
